const TINY_REFERENCE_SHA256 = '975e541e078172bd9c922634e5252112a2e8b9bcdf1003baf5347a42b2b1d557';

export function gappedOpusMp4Fixture(kind: 'ordinary' | 'subpacket' = 'ordinary'): Readonly<{ file: File; reference: Float32Array }> {
	const encoded = kind === 'ordinary' ? SHORT_ENCODED : TINY_ENCODED;
	const reference = kind === 'ordinary' ? SHORT_REFERENCE : TINY_REFERENCE;
	const bytes = Uint8Array.from(inflateSync(Buffer.from(encoded.join(''), 'base64')));
	const decoded = Uint8Array.from(inflateSync(Buffer.from(reference.join(''), 'base64')));
	assert.equal(createHash('sha256').update(bytes).digest('hex'), kind === 'ordinary' ? SHORT_ENCODED_SHA256 : TINY_ENCODED_SHA256);
	assert.equal(createHash('sha256').update(decoded).digest('hex'), kind === 'ordinary' ? SHORT_REFERENCE_SHA256 : TINY_REFERENCE_SHA256);
	return { file: new File([bytes.buffer], 'Recording.m4a', { type: 'audio/mp4' }), reference: new Float32Array(decoded.buffer).slice(0, kind === 'ordinary' ? 14400 : 10080) };
}
